# owner: platform
import unittest
from tests.support import data_file
from hourglass.timesheet import format_timesheet
from hourglass.schedule import load_schedule
from hourglass.models import Shift, Span

def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start, end))

class TimesheetTests(unittest.TestCase):
    def test_sample_schedule(self):
        shifts = load_schedule(data_file("schedule.csv"))
        lines = format_timesheet(shifts)
        self.assertEqual(len(lines), 3)
        self.assertTrue(lines[0].startswith("Brisa: "))
        self.assertTrue(lines[0].endswith(", 9.0 hours"))

    def test_busiest_first(self):
        lines = format_timesheet(
            [
                make_shift("Odell", 540, 600),
                make_shift("Quill", 540, 720),
                make_shift("Odell", 700, 760),
            ]
        )
        self.assertEqual(
            lines,
            [
                "Quill: 1 shift, 3.0 hours",
                "Odell: 2 shifts, 2.0 hours",
            ],
        )

    def test_one_decimal(self):
        shifts = [make_shift("Odell", 540, 625)]
        self.assertEqual(
            format_timesheet(shifts),
            ["Odell: 1 shift, 1.4 hours"],
        )

    def test_ties_by_name(self):
        lines = format_timesheet(
            [
                make_shift("Quill", 540, 600),
                make_shift("Odell", 540, 600),
            ]
        )
        self.assertTrue(lines[0].startswith("Odell"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            format_timesheet([])

    def test_blank_worker(self):
        for name in ("", "   "):
            shifts = [make_shift(name, 540, 600)]
            with self.assertRaises(ValueError):
                format_timesheet(shifts)
